package local.lito381.server;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** 在實際 accepted Frame 的新 MP 入口，驗證真實 STOPPED 與 DRAINING。 */
public final class CompanionManaAdmissionProbe extends NativeCombatAttackerRegression {
 public static volatile boolean debugReached,mutationVerified,protocolFailed;static boolean before;static int count,staleDebits,frames;static final List<String> rows=new ArrayList<>();
 static final class IOCheck implements AutoCloseable {
  final ClientSession pc;final java.net.Socket old;int locked;
  IOCheck(ClientSession pc,ClientSession owner,GameHub hub,Actor actor)throws Exception{this.pc=pc;old=(java.net.Socket)get(pc,"socket");set(pc,"socket",new java.net.Socket(){public java.io.OutputStream getOutputStream()throws java.io.IOException{return new java.io.FilterOutputStream(old.getOutputStream()){public void write(byte[]b,int o,int n)throws java.io.IOException{if(pc.nativePlayerActionLock().isHeldByCurrentThread()||owner.nativePlayerActionLock().isHeldByCurrentThread()||Thread.holdsLock(hub)||Thread.holdsLock(actor.raw())||Thread.holdsLock(getUnchecked(actor.raw(),"timedStatus"))||Thread.holdsLock(getUnchecked(owner,"tamedCompanions"))||Thread.holdsLock(CombatPoisonAtomic.status(pc))||Thread.holdsLock(CombatPoisonAtomic.status(owner))||Thread.holdsLock(NativePlayerLifetime.of(hub).admission)||NativePlayerCommit.vitalLockHeld())locked++;out.write(b,o,n);}public void write(int b)throws java.io.IOException{write(new byte[]{(byte)b},0,1);}};}public void close(){}});}
  public void close()throws Exception{set(pc,"socket",old);}
 }
 static int packet(SourceActionPairProbe.Wire wire,byte[] expected)throws Exception{var cipher=new Protocol.CipherState(0);set(cipher,"value",wire.seed);var raw=wire.raw.toByteArray();int count=0;for(int at=0;at<raw.length;){int n=(raw[at]&255)|((raw[at+1]&255)<<8);check(n>=3&&at+n<=raw.length,"complete actual encrypted transfer output");var plain=cipher.decrypt(Arrays.copyOfRange(raw,at+2,at+n));if(Arrays.equals(plain,expected))count++;at+=n;}return count;}
 static int stoppedRejected,drainingCommitted;
 static void one(ClientSession pc,ClientSession owner,GameHub hub,String label)throws Exception{
  var actor=fresh(pc,owner,hub,label);mp(actor,20);catalog(rule(77,-1,100,0,0,7,false,0,0,false,0,0));int hp=hp(actor);debugReached=false;mutationVerified=false;boolean drain=before;var failure=new java.util.concurrent.atomic.AtomicReference<Throwable>();Thread closing=null;
  try(var wire=new SourceActionPairProbe.Wire(pc,owner);var masterWire=new SourceActionPairProbe.Wire(owner,pc);var strict=new IOCheck(pc,owner,hub,actor);var masterStrict=new IOCheck(owner,pc,hub,actor)){var release=hold();NativePlayerCommit.Event event;try{event=fire(pc,owner,actor);}finally{release.countDown();}long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(!debugReached&&System.nanoTime()<until)Thread.sleep(1);check(debugReached&&NativePlayerCommit.integer(actor.raw(),"mp")==20&&(int)get(pc,"playerMp")==20&&(int)get(pc,"playerHp")==4000-event.damage(),"actual accepted Frame pauses at new transfer entry after HP and before MP");frames++;var life=NativePlayerLifetime.of(hub);closing=new Thread(()->{try{NativePlayerLifetime.shutdown(hub,drain,drain?5000:0);}catch(Throwable e){failure.set(e);}},"fixture-real-MP-admission-close");closing.start();
   until=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);var mode=drain?NativePlayerLifetime.Mode.DRAINING:NativePlayerLifetime.Mode.STOPPED;while(life.mode!=mode&&System.nanoTime()<until)Thread.sleep(1);check(life.mode==mode&&failure.get()==null,"real lifetime reached the selected admission mode before MP entry");if(drain)check(closing.isAlive(),"actual drain retains its already-owned PC Frame");else{closing.join(3000);check(!closing.isAlive(),"actual nondrain shutdown completed before MP entry");}
   mutationVerified=true;closing.join(7000);settle(hub);check(!closing.isAlive()&&failure.get()==null&&life.mode==NativePlayerLifetime.Mode.STOPPED,"actual close and accepted transfer finish without lock cycle");check(mp(actor)==(drain?13:20)&&(int)get(pc,"playerMp")== (drain?27:20),"DRAINING finishes the owned pair; STOPPED rejects both NPC debit and player credit");if(drain)drainingCommitted++;else stoppedRejected++;check(hp(actor)==hp&&(int)get(owner,"playerHp")==4000&&(int)get(owner,"playerMp")==20,"admission preserves actor HP and master resources");check(NativeCombatAttacker.idle()&&NativePlayerCommit.frame()==null&&NativePlayerCommit.pending()==0&&NativePlayerCommit.failed()==0&&NativePlayerVitalCompletions.pending(life)==0,"all accepted Frame and completion receipts retire");check(strict.locked+masterStrict.locked+wire.locked+masterWire.locked==0,"actual completion IO outside every transfer lock");check(packet(wire,Protocol.manaPoint(27,(int)get(pc,"playerMaxMp")))==(drain?1:0)&&packet(masterWire,Protocol.manaPoint(27,(int)get(pc,"playerMaxMp")))==0,"one original matching MP packet only for the committed owned transfer");rows.add(label+" drain="+drain);count++;
  }catch(Throwable e){protocolFailed=true;throw e;}
 }
 public static void main(String[]args)throws Exception{
  var jar=Path.of(args[3]).toRealPath();for(var type:List.of(ClientSession.class,NativePlayerCommit.class,NativeCombatAttacker.class,NativeEquipmentDefense.class))check(Path.of(type.getProtectionDomain().getCodeSource().getLocation().toURI()).toRealPath().equals(jar),"actual immutable Frame/actor/equipment classes");var base=copy(ServerConfig.load(Path.of(args[0]),"standard"),Map.of("battleNaturalHpRegenEnabled",false,"battleNaturalMpRegenEnabled",false,"uncannyDodgeHitFixtureD20",20,"uncannyDodgeHitFixtureD100",1,"mortalBodyFixtureD100",1));ResourceDatabase.load(base);catalogField=NativeArmorProc.class.getDeclaredField("current");catalogField.setAccessible(true);var original=NativeArmorProc.catalog();for(int id=20000;id<22000;id++){var d=InventoryCatalog.find(id);if(d!=null&&d.sourceArmor()&&d.sourceArmorStatus().armorType()==2){armor=copy(d,Map.of("catalogId",5001L,"unitWeight",1,"sourceArmorStatus",copy(d.sourceArmorStatus(),Map.of("classMask",127))));break;}}check(armor!=null,"native armor action fixture");var templates=new NativeDeItemTemplatesResources.Owner().reload(base);var definitions=new NativeDeItemDefinitionsResources.Owner().reload(base);var root=Path.of(args[1]);
  try{for(boolean drain:new boolean[]{false,true})for(boolean app:new boolean[]{false,true})for(String label:List.of("WORLD-COMPANION-PET","WORLD-COMPANION-SUMMON","WORLD-COMPANION-TAMED")){before=drain;var dir=root.resolve(drain+"-"+app+"-"+label);Files.createDirectories(dir);var cfg=copy(base,Map.of("statePersistenceEnabled",true,"stateFile",dir.resolve("must-not-write.properties")));var store=new GameStateStore(dir.resolve("must-not-write.properties"),false,true);var accounts=new MemoryAccountRepository("fixture","fixture","",0,1,40,52);
   try(var capture=new CaptureLog(dir.resolve("capture"));var hub=new GameHub(cfg,store,accounts);var f=new SourceLoginRegression.Fixture(cfg,accounts,store,capture,hub,0,ClientSession.Endpoint.GAME);var p=new SourceLoginRegression.Fixture(cfg,accounts,store,capture,hub,0,ClientSession.Endpoint.GAME);var m=new SourceLoginRegression.Fixture(cfg,accounts,store,capture,hub,0,ClientSession.Endpoint.GAME);var o=new SourceLoginRegression.Fixture(cfg,accounts,store,capture,hub,0,ClientSession.Endpoint.GAME)){var clock=(ScheduledExecutorService)get(hub,"battleClock");clock.shutdownNow();check(clock.awaitTermination(2,TimeUnit.SECONDS),"unrelated fixture clock stopped");var fixtures=List.of(f,p,m,o);for(int i=0;i<4;i++){var pc=fixtures.get(i).session;NativeDirectoryRegression.init(fixtures.get(i),"DebitFrame"+i,0,cfg.classicServerNames().get(0));var c=((List<CharacterSummary>)get(pc,"characters")).get(0);set(pc,"characters",List.of(copy(c,Map.of("objectId",0x3c000001L+i,"level",99,"type",0))));set(pc,"sourceEquipmentMagicStats",SourceEquipmentMagicStats.none());set(pc,"sourcePhysicalGrowthStats",SourcePhysicalGrowthStats.classic381());}FlowRegression.setup(hub,f.session,p.session,m.session,o.session);if(app)NativeDeItemApplication.install(hub,templates,definitions);room=(long)get(p.session,"currentRoomId");roomState=FlowRegression.room(hub,room);oldRules=((BattleRules.MatchState)get(roomState,"match")).rules();one(p.session,f.session,hub,label);}check(!Files.exists(dir.resolve("must-not-write.properties")),"memory-only accepted Frame fixture");
  }}finally{catalogField.set(null,original);NativePlayerCommit.closeFixture();}check(count==12&&frames==12&&stoppedRejected==6&&drainingCommitted==6&&NativePlayerLifetime.allIdle(),"all original accepted Frames retire MP side effects correctly");Files.write(Path.of(args[2]).resolveSibling("cases.txt"),rows);Files.writeString(Path.of(args[2]),"{\"cases\":"+count+",\"checks\":"+checks+",\"actual_accepted_Frames\":"+frames+",\"STOPPED_rejected_pairs\":"+stoppedRejected+",\"DRAINING_owned_committed_pairs\":"+drainingCommitted+",\"full_goal_achieved\":false}\n");
 }
}
